fn swap_first_and_last(a: &mut Vec<i32>) {
    let n = a.len();
    if n >= 2 {
        a.swap(0, n - 1);
    }
}

fn main() {
    // Example usage
    let mut v1 = vec![1, 2, 3, 4, 5];
    swap_first_and_last(&mut v1);
    assert_eq!(v1, vec![5, 2, 3, 4, 1]);

    let mut v2 = vec![42];
    swap_first_and_last(&mut v2);
    assert_eq!(v2, vec![42]);

    println!("All tests passed!");
}